import{_ as a,o as n,c as e,a5 as t}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"FR 3.5.1 — Tạo gói Agency và gói workspace","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/3-5-1-create-media-package/spec.md","filePath":"feature/media-package-campaign/3-5-1-create-media-package/spec.md"}'),h={name:"feature/media-package-campaign/3-5-1-create-media-package/spec.md"};function c(g,i,r,o,l,p){return n(),e("div",null,[...i[0]||(i[0]=[t('<h1 id="fr-3-5-1-—-tao-goi-agency-va-goi-workspace" tabindex="-1">FR 3.5.1 — Tạo gói Agency và gói workspace <a class="header-anchor" href="#fr-3-5-1-—-tao-goi-agency-va-goi-workspace" aria-label="Permalink to &quot;FR 3.5.1 — Tạo gói Agency và gói workspace&quot;">​</a></h1><p>Cập nhật BA 2026-11-05, chờ triển khai. Theo <a href="./../guest-sharing-manager-led/spec.html">spec hành trình mới</a>.</p><h2 id="muc-tieu-va-vai-tro" tabindex="-1">Mục tiêu và vai trò <a class="header-anchor" href="#muc-tieu-va-vai-tro" aria-label="Permalink to &quot;Mục tiêu và vai trò&quot;">​</a></h2><p>Owner tạo gói của Agency để quảng bá. Manager ghi nhận gói thực hiện của workspace sau khi chốt với Client bên ngoài hệ thống. Admin template vẫn thuộc phạm vi quản lý riêng của Admin.</p><h2 id="tieu-chi-nghiem-thu" tabindex="-1">Tiêu chí nghiệm thu <a class="header-anchor" href="#tieu-chi-nghiem-thu" aria-label="Permalink to &quot;Tiêu chí nghiệm thu&quot;">​</a></h2><ul><li>Owner tạo gói Agency độc lập với workspace, theo quyền danh mục hiện hành. Có thể tham khảo nguồn mẫu được phép.</li><li>Gói dùng các dịch vụ, mô tả, tiêu chí, tổng sản lượng và đơn vị hiện hành. Ngân sách/thời lượng tùy chọn, có giá trị thì phải hợp lệ.</li><li>Owner xuất nội dung đã lưu thành ảnh/PDF hoặc chia sẻ link guest. Link hiển thị bản Agency mới nhất đã lưu, file là bản tại thời điểm xuất.</li><li>Owner tạo workspace và gán Manager khi chưa có Client. Manager không phải chờ Client tham gia để chuẩn bị gói.</li><li>Manager chọn gói Agency phù hợp để tùy chỉnh hoặc tạo gói workspace mới theo thỏa thuận bên ngoài.</li><li>Gói workspace giữ nội dung riêng. Sửa danh mục Agency không tự sửa gói workspace, Campaign hoặc task.</li><li>Lưu gói workspace hợp lệ tự tạo một Campaign DRAFT và task lớn theo gói. Lưu lại/retry không tạo trùng.</li><li>Manager không cần thêm lượt duyệt Owner hoặc Client để lưu gói. Client xem gói đã ghi nhận sau khi tham gia.</li><li>Có thể chỉnh trước triển khai và đồng bộ an toàn với Campaign/task. Khi triển khai phải cố định bản sử dụng, khóa gói theo spec mới.</li><li>i18n vi/en song song, semantic light/dark, bàn phím và mobile. Trạng thái tải/lưu/trống/lỗi/thiếu quyền rõ ràng.</li></ul><h2 id="ranh-gioi" tabindex="-1">Ranh giới <a class="header-anchor" href="#ranh-gioi" aria-label="Permalink to &quot;Ranh giới&quot;">​</a></h2><p>Quyền xuất/share danh mục thuộc Owner. Không biến gói workspace thành gói công khai. Chi tiết API, vòng đời share và mapping dữ liệu cũ sẽ chốt trong plan, không dùng endpoint chọn/duyệt Client cũ làm hợp đồng cho flow mới.</p>',8)])])}const m=a(h,[["render",c]]);export{u as __pageData,m as default};
